import {QrkAuthService} from '../data/qrk-auth-service.js';
import {resolveQrkConfig} from '../data/qrk-config.js';
import {DEVELOPMENT_CLIENTS,QRK_CLIENTS_KEY,SERVICE_PRESETS,describeServiceProfile,normalizeServiceProfile,presetSettings} from '../data/qrk-service-presets.js';
const $=selector=>document.querySelector(selector),$$=selector=>[...document.querySelectorAll(selector)],CLIENTS_KEY=QRK_CLIENTS_KEY,authService=new QrkAuthService(resolveQrkConfig());
let clients=readClients(),toastTimer;
function readClients(){let saved=[];try{const value=JSON.parse(localStorage.getItem(CLIENTS_KEY)||'[]');if(Array.isArray(value))saved=value}catch{}const canonicalSlugs=new Set(DEVELOPMENT_CLIENTS.map(client=>client.slug)),merged=[...saved.filter(client=>!canonicalSlugs.has(client.slug)),...DEVELOPMENT_CLIENTS];localStorage.setItem(CLIENTS_KEY,JSON.stringify(merged));return merged}
function saveClients(){localStorage.setItem(CLIENTS_KEY,JSON.stringify(clients))}
function esc(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function segment(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')}
function usernameSegment(value){return String(value||'').toLowerCase().replace(/[^a-z0-9_-]+/g,'')}
function announce(message){const toast=$('#platform-toast');toast.textContent=message;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,3200)}
function initializeThemeEditor(){
  const nav=$('.platform-sidebar nav'),workspace=$('.platform-content');
  nav.insertAdjacentHTML('beforeend','<button type="button" data-admin-view="appearance">Appearance</button>');
  const fields=[['accent','Accent','Buttons, links, and active states'],['page','Page background','Workspace canvas'],['surface','Surface','Cards and top bars'],['text','Text','Primary content'],['sidebar','Sidebar','Global navigation background'],['muted','Muted text','Secondary labels and descriptions'],['border','Borders','Cards, fields, and dividers'],['icon','Icon background','Small icon tiles and quiet controls'],['badge','Navigation badge','Menu count and alert badges'],['badgeText','Badge number text','Numbers shown inside badges'],['success','Success','Available, open, and completed states'],['warning','Warning','Attention and waiting states'],['danger','Danger','Errors and destructive actions']];
  const fieldMarkup=fields.map(([key,label,help])=>`<label class="theme-color-field"><input type="color" name="${key}"><span>${label}<small>${help}</small></span></label>`).join('');
  workspace.insertAdjacentHTML('beforeend',`<section data-view-panel="appearance" hidden><div class="platform-heading"><div><p class="eyebrow">GLOBAL STYLES</p><h1>Appearance.</h1><p>Choose a ready-made theme or fine-tune every shared color.</p></div></div><section class="platform-card theme-section"><div class="platform-card-heading"><div><h2>Theme</h2><p>Select the active website mode and a complete preset.</p></div><div class="theme-mode-switch" role="group" aria-label="Website color mode"><button type="button" data-theme-mode="light">Light</button><button type="button" data-theme-mode="dark">Dark</button></div></div><div class="theme-preset-groups"><div><h3>Light mode presets</h3><div class="theme-preset-grid" data-preset-grid="light"></div></div><div><h3>Dark mode presets</h3><div class="theme-preset-grid" data-preset-grid="dark"></div></div></div></section><details class="platform-card advanced-theme"><summary><span><strong>Advanced settings</strong><small>Edit all global tokens independently for light and dark mode.</small></span><span aria-hidden="true">+</span></summary><form id="theme-form"><div class="advanced-mode-tabs" role="tablist" aria-label="Advanced color mode"><button type="button" role="tab" data-edit-mode="light">Light mode colors</button><button type="button" role="tab" data-edit-mode="dark">Dark mode colors</button></div><div class="theme-color-grid">${fieldMarkup}</div><p class="theme-note">Changes preview immediately. Readable foreground colors are chosen automatically for the accent and sidebar.</p><div class="theme-actions"><button class="button outline" type="button" id="reset-theme">Reset this mode</button><button class="button primary" type="submit">Save custom colors</button></div></form></details><section class="platform-card theme-preview" aria-label="Theme preview"><div class="platform-card-heading"><div><h2>Live preview</h2><p>Representative dashboard surfaces</p></div></div><div class="theme-preview-window"><div class="theme-preview-top"></div><div class="theme-preview-body"><div class="theme-preview-nav"><b class="theme-preview-brand">QRK</b><span>Dashboard</span></div><div class="theme-preview-content"><strong>Business overview</strong><span>Today at a glance</span><div class="theme-preview-cards"><i></i><i></i><i></i><i></i></div></div></div></div></section></section>`);
  const form=$('#theme-form'),api=window.QrkGlobalTheme;
  let editMode=api.readState().mode;
  const renderPresets=()=>{const state=api.readState();for(const mode of ['light','dark']){$(`[data-preset-grid="${mode}"]`).innerHTML=Object.entries(api.presets[mode]).map(([id,preset])=>`<button class="theme-preset${state[`${mode}Preset`]===id?' selected':''}" type="button" data-use-preset="${id}" data-preset-mode="${mode}" aria-pressed="${state[`${mode}Preset`]===id}"><span class="preset-swatches">${['sidebar','accent','page','surface'].map(key=>`<i style="--preset-color:${preset.colors[key]}"></i>`).join('')}</span><strong>${preset.name}</strong><small>${preset.description}</small></button>`).join('')}};
  const fill=theme=>api.tokenKeys.forEach(key=>form.elements[key].value=theme[key]);
  const values=()=>Object.fromEntries(api.tokenKeys.map(key=>[key,form.elements[key].value]));
  const sync=()=>{const state=api.readState();$$('[data-theme-mode]').forEach(button=>{const active=button.dataset.themeMode===state.mode;button.classList.toggle('active',active);button.setAttribute('aria-pressed',active)});$$('[data-edit-mode]').forEach(button=>{const active=button.dataset.editMode===editMode;button.classList.toggle('active',active);button.setAttribute('aria-selected',active)});fill(state[editMode]);renderPresets()};
  sync();
  document.addEventListener('click',event=>{const modeButton=event.target.closest('[data-theme-mode]');if(modeButton){api.setMode(modeButton.dataset.themeMode);editMode=modeButton.dataset.themeMode;sync();announce(`${editMode==='dark'?'Dark':'Light'} mode applied`)}const editButton=event.target.closest('[data-edit-mode]');if(editButton){editMode=editButton.dataset.editMode;sync()}const presetButton=event.target.closest('[data-use-preset]');if(presetButton){editMode=presetButton.dataset.presetMode;api.usePreset(editMode,presetButton.dataset.usePreset);sync();announce(`${api.presets[editMode][presetButton.dataset.usePreset].name} preset applied`)}});
  form.addEventListener('input',()=>api.apply(values(),editMode));
  form.addEventListener('submit',event=>{event.preventDefault();api.save(values(),editMode,'custom');sync();announce(`${editMode==='dark'?'Dark':'Light'} custom colors saved`)});
  $('#reset-theme').addEventListener('click',()=>{api.reset(editMode);sync();announce(`${editMode==='dark'?'Dark':'Light'} colors reset`)});
}
function clientRow(client){const active=client.status==='active',profile=normalizeServiceProfile(client.serviceProfile||{preset:'quick'}),preset=SERVICE_PRESETS[profile.preset];return `<article class="platform-client-row" data-client-id="${esc(client.id)}"><div class="platform-client"><span>${esc(client.businessName.charAt(0).toUpperCase())}.</span><div><strong>${esc(client.businessName)}</strong><small>${esc(preset.name)} · ${esc(profile.locationName)}</small></div></div><code>${esc(client.prefix)}.</code><span class="platform-status${active?'':' inactive'}">${active?'Active':'Paused'}</span><div class="platform-row-actions"><button class="button primary" type="button" data-open-client>Admin workspace</button><a class="button outline" href="/menu/?business=${encodeURIComponent(client.slug)}">Customer view</a><button class="button subtle" type="button" data-toggle-client>${active?'Pause':'Activate'}</button></div></article>`}
function adminRow(client){return `<article class="platform-account-row"><div><strong>${esc(client.admin.name)}</strong><small>${esc(client.admin.email)}</small></div><span>${esc(client.businessName)}</span><code>${esc(client.admin.username)}</code><span class="platform-status">${esc(client.admin.access||'First login pending')}</span></article>`}
function render(){const active=clients.filter(client=>client.status==='active').length,count=clients.length;$('#metric-client-count').textContent=count;$('#metric-active-count').textContent=active;$('#metric-admin-count').textContent=count;$('#nav-client-count').textContent=count;$('#client-count-label').textContent=`${count} ${count===1?'client':'clients'}`;$('#admin-count-label').textContent=`${count} ${count===1?'account':'accounts'}`;$('#client-list').innerHTML=clients.map(clientRow).join('');$('#recent-client-list').innerHTML=clients.slice(-3).reverse().map(clientRow).join('');$('#admin-list').innerHTML=clients.map(adminRow).join('')}
function showView(view){$$('[data-view-panel]').forEach(panel=>panel.hidden=panel.dataset.viewPanel!==view);$$('nav [data-admin-view]').forEach(button=>button.classList.toggle('nav-active',button.dataset.adminView===view));const labels={overview:'QRK Admin overview',clients:'Client portals',accounts:'Client Admins',appearance:'Global appearance'};$('#platform-page-title').textContent=labels[view];document.title=`QRK MENU — ${labels[view]}`;window.scrollTo(0,0)}
function selectedPreset(){return $('#preset-grid input:checked')?.value||'traditional'}
function readServiceProfile(){const form=$('#client-form'),preset=selectedPreset(),settings=presetSettings(preset);for(const key of ['tableIdentification','joinPolicy','guestOrderPolicy','proximityPolicy'])settings[key]=form.elements[key].value;settings.proximityRadiusM=Number(form.elements.proximityRadiusM.value)||250;settings.staffAcceptance=form.elements.staffAcceptance.checked;settings.additionalDevices=settings.joinPolicy!=='disabled';return normalizeServiceProfile({preset,locationName:form.elements.locationName.value.trim()||'Main location',settings})}
function applyPreset(id){const form=$('#client-form'),settings=presetSettings(id);for(const key of ['tableIdentification','joinPolicy','guestOrderPolicy','proximityPolicy'])form.elements[key].value=settings[key];form.elements.proximityRadiusM.value=settings.proximityRadiusM;form.elements.staffAcceptance.checked=settings.staffAcceptance;$('#table-rules').hidden=settings.serviceMode!=='table';updateFormPreviews()}
function updateFormPreviews(){const form=$('#client-form'),name=form.elements.businessName.value,slug=segment(form.elements.slug.value||name),prefix=usernameSegment(form.elements.prefix.value||segment(name).split('-')[0]),suffix=usernameSegment(form.elements.adminUsername.value)||'admin';$('#slug-preview').textContent=slug||'business-name';$('#admin-prefix-preview').textContent=`${prefix||'client'}.`;$('#admin-username-preview').textContent=`Login username: ${prefix||'client'}.${suffix}`;$('#journey-preview').textContent=describeServiceProfile(readServiceProfile())}
function openClientDialog(){const form=$('#client-form');form.reset();$('#client-form-error').textContent='';$('#preset-grid').innerHTML=Object.values(SERVICE_PRESETS).map((preset,index)=>`<label class="preset-card"><input type="radio" name="preset" value="${preset.id}" ${preset.id==='traditional'?'checked':''}><span><strong>${esc(preset.name)}</strong><small>${esc(preset.summary)}</small></span></label>`).join('');applyPreset('traditional');updateFormPreviews();$('#client-dialog').showModal();form.elements.businessName.focus()}
$('#platform-continue').addEventListener('click',()=>{$('#platform-login').hidden=true;$('#platform-shell').hidden=false;showView('overview');render()});
$('#platform-logout').addEventListener('click',()=>{$('#platform-shell').hidden=true;$('#platform-login').hidden=false;document.title='QRK MENU — QRK Admin';$('#platform-continue').focus()});
document.addEventListener('click',event=>{const view=event.target.closest('[data-admin-view]');if(view)showView(view.dataset.adminView);if(event.target.closest('[data-add-client]'))openClientDialog();if(event.target.closest('.close-dialog'))event.target.closest('dialog').close();const openClient=event.target.closest('[data-open-client]');if(openClient){const id=openClient.closest('[data-client-id]').dataset.clientId,client=clients.find(item=>item.id===id);try{authService.signInDevelopment({displayName:client.admin.name,username:client.admin.username,businessId:`preview:${client.slug}`,businessName:client.businessName,businessSlug:client.slug,role:'admin',permissions:{viewOrders:true,acceptOrders:true,prepareOrders:true,markReady:true,completeOrders:true,cancelOrders:true,changeAvailability:true,editMenu:true,viewOrderHistory:true,viewSales:true,manageStaff:true}});location.href='/'}catch(reason){announce(reason.message)}}const toggle=event.target.closest('[data-toggle-client]');if(toggle){const id=toggle.closest('[data-client-id]').dataset.clientId,client=clients.find(item=>item.id===id);client.status=client.status==='active'?'paused':'active';saveClients();render();announce(`${client.businessName} ${client.status==='active'?'activated':'paused'} in this preview`)}});
const clientForm=$('#client-form');
clientForm.elements.businessName.addEventListener('input',event=>{if(!clientForm.elements.slug.dataset.edited)clientForm.elements.slug.value=segment(event.target.value);if(!clientForm.elements.prefix.dataset.edited)clientForm.elements.prefix.value=usernameSegment(segment(event.target.value).split('-')[0]);updateFormPreviews()});
clientForm.elements.slug.addEventListener('input',event=>{event.target.dataset.edited='true';event.target.value=segment(event.target.value);updateFormPreviews()});clientForm.elements.prefix.addEventListener('input',event=>{event.target.dataset.edited='true';event.target.value=usernameSegment(event.target.value);updateFormPreviews()});clientForm.elements.adminUsername.addEventListener('input',event=>{event.target.value=usernameSegment(event.target.value);updateFormPreviews()});clientForm.addEventListener('reset',()=>{delete clientForm.elements.slug.dataset.edited;delete clientForm.elements.prefix.dataset.edited;requestAnimationFrame(updateFormPreviews)});
clientForm.addEventListener('change',event=>{if(event.target.name==='preset')applyPreset(event.target.value);else updateFormPreviews()});clientForm.elements.locationName.addEventListener('input',updateFormPreviews);clientForm.elements.proximityRadiusM.addEventListener('input',updateFormPreviews);
clientForm.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget,businessName=form.elements.businessName.value.trim(),slug=segment(form.elements.slug.value),prefix=usernameSegment(form.elements.prefix.value),suffix=usernameSegment(form.elements.adminUsername.value),username=`${prefix}.${suffix}`,error=$('#client-form-error');error.textContent='';if(clients.some(client=>client.slug===slug)){error.textContent='That portal slug is already in use.';form.elements.slug.focus();return}if(clients.some(client=>client.prefix===prefix)){error.textContent='That username prefix is already in use.';form.elements.prefix.focus();return}let credentials;try{credentials=authService.createPreviewUser({displayName:form.elements.adminName.value.trim(),username,email:form.elements.adminEmail.value.trim(),role:'admin',permissions:{viewOrders:true,acceptOrders:true,prepareOrders:true,markReady:true,completeOrders:true,cancelOrders:true,changeAvailability:true,editMenu:true,viewOrderHistory:true,viewSales:true,manageStaff:true},businessId:`preview:${slug}`,businessName,businessSlug:slug,active:true})}catch(reason){error.textContent=reason.message;return}clients.push({id:`client-${Date.now()}`,businessName,slug,prefix,status:'active',createdAt:new Date().toISOString(),serviceProfile:readServiceProfile(),admin:{name:form.elements.adminName.value.trim(),email:form.elements.adminEmail.value.trim(),username,access:'First login pending'}});saveClients();render();$('#client-dialog').close();$('#created-admin-username').textContent=credentials.username;$('#created-admin-password').textContent=credentials.temporaryPassword;$('#credentials-dialog').showModal();announce(`${businessName} client portal created`)});
$('#copy-client-login').addEventListener('click',async()=>{const value=`QRK MENU Client Admin login\nUsername: ${$('#created-admin-username').textContent}\nTemporary password: ${$('#created-admin-password').textContent}\nPortal: ${location.origin}/`;try{await navigator.clipboard.writeText(value);announce('Client Admin login copied')}catch{announce('Copy the login details shown')}});initializeThemeEditor();render();
